-- The Sample world at the SQL level (D88, Law 7). Run on a THROWAWAY database after the shim and
-- 0001 to 0006, with the world generated by scripts/sample-world-sql.mjs (see README.md here):
--   psql -d <throwaway> -v seed=/path/to/world.sql -f supabase/tests/sample_world_check.sql
-- 1. A small field test is written and every field number the app shows is taken: /how's field
--    totals (lib/field/summary.ts), the field library count, the officer's field Pulse, Lamps and
--    practices, a field master's room, and the open data cards.
-- 2. The whole Sample world is written beside it.
-- 3. Every field number must be exactly what it was, and the Sample side must light up.
\set ON_ERROR_STOP 1
\pset tuples_only on
\pset format unaligned

create function pg_temp.check(ok boolean, msg text) returns void language plpgsql as $$
begin
  if not ok then raise exception 'SAMPLE WORLD CHECK FAILED: %', msg; end if;
  raise notice 'ok  %', msg;
end $$;

-- ── 1. A small field test (is_sample = false) ─────────────────────────────────
insert into auth.users (id) select ('f0000000-0000-4000-8000-0000000000' || lpad(i::text, 2, '0'))::uuid
  from generate_series(1, 12) i;
insert into public.profiles (id, role, display_name, district, is_sample, consented_at)
select ('f0000000-0000-4000-8000-0000000000' || lpad(i::text, 2, '0'))::uuid, 'teacher', null, 'Koppal', false,
  now() - (i || ' days')::interval
from generate_series(1, 7) i;
insert into public.profiles (id, role, display_name, district, is_sample, consented_at) values
  ('f0000000-0000-4000-8000-000000000010', 'master', 'Field Master', 'Koppal', false, now() - interval '9 days'),
  ('f0000000-0000-4000-8000-000000000011', 'officer', 'Field Officer', 'Koppal', false, now() - interval '9 days');
insert into public.masters (id, profile_id, show_name, consented_at, is_sample) values
  ('f1000000-0000-4000-8000-000000000001', 'f0000000-0000-4000-8000-000000000010', 'full', now() - interval '9 days', false);
insert into public.interviews (id, master_id, is_sample)
  values ('f2000000-0000-4000-8000-000000000001', 'f1000000-0000-4000-8000-000000000001', false);
insert into public.segments (interview_id, idx, start_ms, end_ms, text_kn)
  values ('f2000000-0000-4000-8000-000000000001', 0, 0, 4000, 'ಕ್ಷೇತ್ರ');
insert into public.cards (id, master_id, title_kn, title_en, problem_kn, problem_en, steps, status, evidence_segment_ids, topic, is_sample)
select 'f3000000-0000-4000-8000-000000000001', 'f1000000-0000-4000-8000-000000000001', 'ಕ', 'Field card', 'ಸ', 'P',
  '[{"kn":"a","en":"a"}]', 'approved', array[(select min(id) from public.segments)], 'letters', false;
insert into public.questions (id, teacher_id, text_redacted, topic, is_sample, created_at)
select ('f4000000-0000-4000-8000-0000000000' || lpad(i::text, 2, '0'))::uuid,
  ('f0000000-0000-4000-8000-0000000000' || lpad((1 + i % 6)::text, 2, '0'))::uuid,
  'field question', 'letters', false, now() - ((i % 6) || ' days')::interval - interval '2 hours'
from generate_series(1, 12) i;
insert into public.answers (id, question_id, status, card_ids, cost_usd, is_sample)
select ('f5000000-0000-4000-8000-0000000000' || lpad(i::text, 2, '0'))::uuid,
  ('f4000000-0000-4000-8000-0000000000' || lpad(i::text, 2, '0'))::uuid, 'answered',
  '{f3000000-0000-4000-8000-000000000001}', 0.02, false
from generate_series(1, 12) i;
insert into public.tried (answer_id, teacher_id, outcome, is_sample)
select ('f5000000-0000-4000-8000-0000000000' || lpad(i::text, 2, '0'))::uuid,
  ('f0000000-0000-4000-8000-0000000000' || lpad((1 + i % 6)::text, 2, '0'))::uuid,
  (case when i % 3 = 0 then 'partly' else 'worked' end)::public.tried_outcome, false
from generate_series(1, 6) i;

-- Every field number the app can show, as one value.
create function pg_temp.field_numbers() returns jsonb language plpgsql as $$
declare out jsonb;
begin
  perform set_config('request.jwt.claim.sub', 'f0000000-0000-4000-8000-000000000011', false); -- field officer
  out := jsonb_build_object(
    'how_masters', (select count(*) from public.masters where not is_sample and consented_at is not null),
    'how_cards', (select count(*) from public.cards where not is_sample and status = 'approved'),
    'how_teachers', (select count(*) from public.profiles where not is_sample and role = 'teacher' and consented_at is not null),
    'how_questions', (select jsonb_build_array(count(*), count(distinct teacher_id)) from public.questions where not is_sample),
    'how_tried', (select coalesce(jsonb_object_agg(outcome, n), '{}') from (select outcome, count(*) n from public.tried where not is_sample group by 1) x),
    'how_first_consent', (select min(consented_at) from public.profiles where not is_sample and role in ('teacher', 'master') and consented_at is not null),
    'library_counts', (select to_jsonb(v) from public.v_library_counts v where not v.is_sample),
    'pulse_summary', (select jsonb_agg(to_jsonb(s) - 'since' - 'until') from public.insights_summary(false) s),
    'pulse_topics', (select jsonb_agg(to_jsonb(t)) from public.insights_topics(false) t),
    'pulse_districts', (select jsonb_agg(to_jsonb(d)) from public.insights_districts(false) d),
    'pulse_practices', (select jsonb_agg(to_jsonb(p)) from public.insights_practices(false, 20) p),
    'lamps', (select jsonb_agg(to_jsonb(l)) from public.insights_lamps(false) l),
    'lamp_masters', (select jsonb_agg(to_jsonb(l)) from public.insights_lamp_masters(false) l),
    'open_cards', (select count(*) from public.open_cards() o where not o.is_sample)
  );
  perform set_config('request.jwt.claim.sub', 'f0000000-0000-4000-8000-000000000010', false); -- field master
  out := out || jsonb_build_object(
    'master_impact', (select jsonb_agg(to_jsonb(m)) from public.master_impact() m),
    'master_cards', (select jsonb_agg(to_jsonb(m)) from public.master_card_impact() m)
  );
  return out;
end $$;

create temp table before as select pg_temp.field_numbers() as n;
select pg_temp.check((select (n ->> 'how_cards')::int = 1 and (n -> 'how_questions' ->> 0)::int = 12 from before),
  'the field test is in place: 1 approved field card, 12 field questions');

-- ── 2. The Sample world ───────────────────────────────────────────────────────
\i :seed

-- ── 3. Field numbers unchanged; the Sample side lit ───────────────────────────
create temp table after as select pg_temp.field_numbers() as n;
select pg_temp.check((select b.n = a.n from before b, after a),
  'every field number is exactly what it was before the Sample world (/how, library, Pulse, Lamps, practices, master room, open data)');

select pg_temp.check((select count(*) = 0 from public.questions q join public.profiles p on p.id = q.teacher_id where q.is_sample <> p.is_sample),
  'no Sample teacher owns a field question, no field teacher a Sample one');
select pg_temp.check((select count(*) = 0 from public.answers a join public.cards c on c.id = any (a.card_ids) where a.is_sample = false and c.is_sample),
  'no field answer cites a Sample card');

-- As the demo officer (Sample).
select set_config('request.jwt.claim.sub', (select id::text from public.profiles where role = 'officer' and is_sample limit 1), false);
select pg_temp.check((select count(*) = 6 from public.insights_districts(true) where district <> 'elsewhere' and asked is not null),
  'Sample Pulse names six districts');
select pg_temp.check((select count(*) = 0 from public.insights_districts(true) where district = 'gadag'),
  'Gadag''s three Sample teachers are never named');
select pg_temp.check((select count(*) = 6 from public.insights_lamps(true) where district <> 'elsewhere' and helped is not null),
  'six Sample lamps are lit');
select pg_temp.check((select count(*) >= 8 from public.insights_topics(true) where asked is not null),
  'eight or more Sample topics show a number');
select pg_temp.check((select count(*) >= 1 from public.insights_topics(true) where asked_suppressed),
  'at least one Sample topic says fewer than 5 teachers');
select pg_temp.check((select asked > 150 and teachers >= 80 from public.insights_summary(true)),
  'the Sample week is busy');
select pg_temp.check((select count(*) = 5 and bool_and(not suppressed) from public.insights_practices(true, 5)),
  'five Sample practices show a number');
select pg_temp.check((select count(*) >= 4 from public.insights_lamp_masters(true) where helped is not null),
  'several Sample masters show whose practice helped in a district');

-- As the demo master (Sharanappa, Sample).
select set_config('request.jwt.claim.sub', (select p.id::text from public.profiles p where p.display_name = 'Sharanappa (Sample)'), false);
select pg_temp.check((select approved_cards = 5 and teachers_reached >= 10 and teachers_worked >= 5 and thanks >= 2 from public.master_impact()),
  'the demo master''s room shows reach, worked and thank you notes');
select pg_temp.check((select count(*) filter (where teachers_tried is not null and teachers_tried >= 3) >= 4 from public.master_card_impact()),
  'four or more of the demo master''s cards show how many teachers tried them');

select pg_temp.check((select approved_cards = 60 and masters_with_cards = 12 from public.v_library_counts where is_sample),
  'the Sample library: 60 approved cards from 12 masters');
select pg_temp.check((select count(*) = 60 from public.open_cards() where is_sample),
  'open data carries the 60 Sample cards, flagged is_sample');

-- What the screens will show, for the report.
\echo '── Sample Pulse (as the demo officer) ──'
select set_config('request.jwt.claim.sub', (select id::text from public.profiles where role = 'officer' and is_sample limit 1), false);
select 'week: asked ' || asked || ', teachers ' || teachers || ', answered ' || answered || ', tried ' || tried || ', worked ' || worked from public.insights_summary(true);
select 'topics: ' || string_agg(topic || ' ' || coalesce(asked::text, case when asked_shielded then 'kept private' else 'fewer than 5' end) || coalesce(' (waiting ' || waiting || ')', ''), ', ') from public.insights_topics(true);
select 'districts: ' || string_agg(district || ' ' || coalesce(asked::text, 'fewer than 5'), ', ') from public.insights_districts(true);
select 'lamps: ' || string_agg(district || ' ' || coalesce(helped::text, 'fewer than 5'), ', ') from public.insights_lamps(true);
select 'practices: ' || string_agg(title_en || ' (' || master_name || ', ' || master_district || ') worked ' || coalesce(worked::text, '?') || ' of ' || coalesce(tried::text, '?'), '; ') from public.insights_practices(true, 5);
\echo '── The demo master''s room ──'
select set_config('request.jwt.claim.sub', (select p.id::text from public.profiles p where p.display_name = 'Sharanappa (Sample)'), false);
select 'master: cards ' || approved_cards || ', reached ' || coalesce(teachers_reached::text, 'a few') || ', tried ' || coalesce(teachers_tried::text, 'a few') || ', worked ' || coalesce(teachers_worked::text, 'a few') || ', thanks ' || thanks from public.master_impact();
\echo 'All Sample world checks passed.'
